import React from 'react';
import { BlogSummary, articleDate, articlePath } from './blog';
export default function ArticleCards({ posts }: { posts: BlogSummary[] }) {
  return <div className="blog-grid">{posts.map(post => <article className="blog-card" key={post.id}>
    {post.image && <a href={articlePath(post.slug)} tabIndex={-1} aria-hidden="true"><img src={post.image} alt="" loading="lazy" /></a>}
    <p className="home-small"><time dateTime={post.publishedAt}>{articleDate(post.publishedAt)}</time></p>
    <h3><a href={articlePath(post.slug)}>{post.title}</a></h3><p>{post.excerpt}</p><a className="home-text-link" href={articlePath(post.slug)}>Read article <span aria-hidden="true">↗</span></a>
  </article>)}</div>;
}
