export interface PageMetadata {
  title: string;
  description: string;
  url: string;
  image?: string;
  type?: 'website' | 'article';
  schema?: object;
  noindex?: boolean;
}

/** One owner replaces the previous page metadata, including legacy template data. */
export function applyMetadata(page: PageMetadata) {
  document.title = page.title;
  document.head.querySelectorAll('link[rel="canonical"], link[hreflang], script[type="application/ld+json"]').forEach(element => element.remove());
  document.head.querySelectorAll('meta').forEach(element => {
    const key = element.getAttribute('name') || element.getAttribute('property') || '';
    if (/^(description|keywords|robots|og:.*|twitter:.*)$/.test(key)) element.remove();
  });
  const canonical = document.createElement('link'); canonical.rel = 'canonical'; canonical.href = page.url; document.head.appendChild(canonical);
  const values = { description: page.description, robots: page.noindex ? 'noindex, follow' : 'index, follow', 'og:type': page.type || 'website', 'og:title': page.title, 'og:description': page.description, 'og:url': page.url, 'og:image': page.image, 'twitter:card': page.image ? 'summary_large_image' : 'summary', 'twitter:title': page.title, 'twitter:description': page.description, 'twitter:image': page.image };
  for (const [key, value] of Object.entries(values)) {
    if (!value) continue;
    const meta = document.createElement('meta'); meta.setAttribute(key.startsWith('og:') ? 'property' : 'name', key); meta.content = value; document.head.appendChild(meta);
  }
  if (page.schema) { const script = document.createElement('script'); script.type = 'application/ld+json'; script.textContent = JSON.stringify(page.schema).replaceAll('<', '\\u003c'); document.head.appendChild(script); }
}
